:root {
  --bg-dark: #0d0d1a;
  --bg-panel: #13132b;
  --bg-card: #1a1a35;
  --accent-cyan: #00f5e4;
  --accent-magenta: #f500b0;
  --accent-yellow: #f5e600;
  --accent-green: #00f56e;
  --text-bright: #ffffff;
  --text-mid: #9999cc;
  --text-dim: #55557a;
  --border-subtle: #2a2a50;
  --fx-active-bg: #1e003a;
  --live-red: #ff3355;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.dashboard {
  background-color: var(--bg-dark);
  border: 1.5px solid var(--border-subtle);
  border-radius: 10px;
  width: 476px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.dash-header {
  background-color: var(--bg-panel);
  border-bottom: 1.5px solid var(--border-subtle);
  padding: 7px 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.header-left {
  display: flex;
  align-items: center;
  gap: 8px;
}

.live-badge {
  background-color: var(--live-red);
  color: var(--text-bright);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  padding: 2px 6px;
  border-radius: 4px;
}

.set-title {
  font-size: 16px;
  font-weight: 800;
  color: var(--accent-cyan);
  letter-spacing: 0.12em;
}

.header-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
}

.set-label {
  font-size: 8px;
  color: var(--text-dim);
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.set-num {
  font-size: 18px;
  font-weight: 800;
  color: var(--accent-magenta);
  line-height: 1;
}

.dash-body {
  display: flex;
  flex: 1;
}

.tracks-panel {
  flex: 1;
  padding: 9px 12px;
  border-right: 1.5px solid var(--border-subtle);
}

.panel-label {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: var(--text-dim);
  margin-bottom: 6px;
  text-transform: uppercase;
}

.track-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.track {
  display: flex;
  align-items: center;
  gap: 6px;
}

.track-name {
  font-size: 9px;
  font-weight: 700;
  color: var(--text-mid);
  letter-spacing: 0.05em;
  width: 54px;
  flex-shrink: 0;
}

.track.active .track-name {
  color: var(--accent-cyan);
}

.track.muted .track-name {
  color: var(--text-dim);
}

.track-bar {
  flex: 1;
  height: 5px;
  background-color: var(--bg-card);
  border-radius: 3px;
  overflow: hidden;
  border: 1px solid var(--border-subtle);
}

.track-fill {
  height: 100%;
  width: var(--w);
  background-color: var(--accent-cyan);
  border-radius: 3px;
}

.track.active .track-fill {
  background-color: var(--accent-green);
}

.track.muted .track-fill {
  background-color: var(--text-dim);
}

.track-vol {
  font-size: 9px;
  font-weight: 700;
  color: var(--text-mid);
  width: 24px;
  text-align: right;
  flex-shrink: 0;
}

.muted-label {
  color: var(--text-dim);
  font-size: 8px;
}

.right-panel {
  width: 158px;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
}

.bpm-block {
  padding: 9px 12px 7px;
  border-bottom: 1.5px solid var(--border-subtle);
  display: flex;
  align-items: center;
  gap: 6px;
}

.bpm-label {
  font-size: 8px;
  font-weight: 700;
  color: var(--text-dim);
  letter-spacing: 0.12em;
}

.bpm-value {
  font-size: 22px;
  font-weight: 800;
  color: var(--accent-yellow);
  line-height: 1;
  flex: 1;
}

.bpm-dots {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background-color: var(--border-subtle);
}

.dot.on {
  background-color: var(--accent-yellow);
}

.fx-panel {
  padding: 8px 12px;
  border-bottom: 1.5px solid var(--border-subtle);
  flex: 1;
}

.fx-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4px;
}

.fx-btn {
  background-color: var(--bg-card);
  color: var(--text-dim);
  border: 1px solid var(--border-subtle);
  border-radius: 4px;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.05em;
  padding: 4px 3px;
  cursor: pointer;
  text-align: center;
}

.fx-btn.active {
  background-color: var(--fx-active-bg);
  color: var(--accent-magenta);
  border-color: var(--accent-magenta);
}

.time-block {
  padding: 7px 12px;
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.time-label {
  font-size: 8px;
  color: var(--text-dim);
  letter-spacing: 0.1em;
  font-weight: 700;
}

.time-value {
  font-size: 17px;
  font-weight: 800;
  color: var(--text-bright);
  letter-spacing: 0.06em;
}

.dash-footer {
  background-color: var(--bg-panel);
  border-top: 1.5px solid var(--border-subtle);
  padding: 6px 14px;
  display: flex;
  align-items: center;
  gap: 8px;
}

.venue {
  font-size: 9px;
  font-weight: 600;
  color: var(--text-mid);
  letter-spacing: 0.05em;
  flex: 1;
}

.date {
  font-size: 9px;
  font-weight: 700;
  color: var(--accent-cyan);
  letter-spacing: 0.08em;
  flex-shrink: 0;
}

.master-vol {
  display: flex;
  align-items: center;
  gap: 5px;
  flex-shrink: 0;
}

.mv-label {
  font-size: 8px;
  font-weight: 700;
  color: var(--text-dim);
  letter-spacing: 0.1em;
}

.mv-bar {
  width: 52px;
  height: 4px;
  background-color: var(--bg-card);
  border-radius: 3px;
  overflow: hidden;
  border: 1px solid var(--border-subtle);
}

.mv-fill {
  width: 75%;
  height: 100%;
  background-color: var(--accent-green);
  border-radius: 3px;
}
